-- Class cards need a concise portrait, while the selected class renders a
-- separate original long-form article. Mechanics remain structured item data.
UPDATE dndshare.item_type
SET fields = fields || jsonb_build_array(jsonb_build_object(
    'name', 'Короткое описание', 'key', 'short_description', 'type', 'text'
))
WHERE id = 9
  AND jsonb_typeof(fields) = 'array'
  AND NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(fields) field
    WHERE field ->> 'key' = 'short_description'
  );

WITH class_lore(aliases, short_description, description) AS (
    VALUES
      (ARRAY['bard', 'бард'],
       'Бард превращает истории, музыку и силу личности в настоящее волшебство.',
       '<p>Для барда мир полон ритмов, имён и историй, способных менять людей не слабее клинка. Он собирает песни в придорожных трактирах, тайны при дворах и легенды у походных костров, а затем сплетает их в собственное искусство.</p><p>Его магия рождается из исполнения и уверенности: верно взятая нота поддерживает союзника, острое слово лишает врага решимости, а старая баллада открывает путь к давно забытому чуду. Хороший бард одинаково внимательно слушает зал и поле боя.</p><p>В приключение его ведут любопытство, слава или история, которую ещё никто не рассказал. Одни ищут потерянные произведения мастеров, другие хотят стать голосом своего поколения, третьи знают, что иногда одна песня способна пережить целое королевство.</p>'),
      (ARRAY['barbarian', 'варвар'],
       'Варвар встречает опасность первобытной силой, несгибаемой волей и яростью защитника.',
       '<p>Варвар полагается не на строевую выучку, а на острое чувство угрозы и силу, воспитанную суровой жизнью. Его родиной могут быть степи, горы, дикие острова или шумный город — важнее внутренняя связь с тем, что не удалось укротить цивилизации.</p><p>Ярость варвара не обязательно слепа. Она может быть памятью предков, холодной решимостью выжить или вспышкой, которая заслоняет друзей от удара. В бою он принимает опасность на себя и продолжает двигаться там, где другие уже остановились бы.</p><p>Он отправляется в путь ради испытания, изгнания, мести или защиты дома. За грозным обликом часто скрывается прямота человека, который ценит поступки выше титулов и навсегда запоминает тех, кто разделил с ним трудную дорогу.</p>'),
      (ARRAY['fighter', 'воин'],
       'Воин достигает мастерства дисциплиной, опытом и безупречным владением оружием.',
       '<p>Воины приходят из армий, рыцарских орденов, городских дружин и школ единоборств. Их объединяет не происхождение, а привычка превращать повторение в мастерство: каждый шаг, стойка и удар отточены до состояния надёжного инструмента.</p><p>Опытный воин читает сражение целиком. Он замечает слабое место в обороне, прикрывает союзника и выбирает оружие под задачу, а не ради красивого жеста. Даже выдающийся природный талант для него остаётся лишь началом долгой работы.</p><p>Одни воины ищут достойного противника, другие служат идеалу или пытаются исправить ошибку прошлого. Их история строится на выборе, ради чего применять накопленное мастерство и кем остаться, когда победа уже одержана.</p>'),
      (ARRAY['wizard', 'волшебник'],
       'Волшебник изучает устройство магии и превращает знание в тщательно подготовленную силу.',
       '<p>Для волшебника магия — язык, который можно исследовать, записывать и совершенствовать. Его книга хранит годы труда: формулы на полях, исправленные ошибки, заметки наставников и открытия, добытые в местах, куда благоразумный учёный не стал бы заходить.</p><p>Сила волшебника заключается в подготовке. Он сравнивает источники, заранее выбирает подходящие заклинания и старается понять природу угрозы до первого столкновения. Но каждая новая тайна напоминает, насколько огромна область ещё неизведанного.</p><p>В дорогу его ведут запретный трактат, исчезнувшая школа, необычное явление или вопрос, не дающий уснуть. Со временем поиск знания становится и нравственным испытанием: не всё, что можно открыть, следует немедленно применять.</p>'),
      (ARRAY['druid', 'друид'],
       'Друид хранит равновесие живого мира и говорит с его древними силами.',
       '<p>Друид видит природу не декорацией, а сложным союзом существ, времён года и стихий. Шёпот листвы, след зверя и перемена ветра для него являются словами языка, который существовал задолго до первых городов.</p><p>Его магия поддерживает жизнь, принимает ярость бури и заимствует облик зверей. Друид может защищать священную рощу, странствовать между поселениями или жить среди людей, напоминая им о цене нарушенного равновесия.</p><p>В приключение он отправляется, когда болезнь касается земли, исчезают духи или чужая жадность угрожает целому краю. Однако природа редко делит мир на добро и зло, поэтому решения друида требуют терпения и взгляда дальше ближайшей победы.</p>'),
      (ARRAY['cleric', 'жрец'],
       'Жрец проводит в мир волю божества, идеала или священной силы.',
       '<p>Жрец посвящает себя силе, которая придаёт смысл его поступкам. Это может быть божество, древний пантеон или великий принцип, но вера для него проявляется не только в обрядах — она проверяется каждым решением вне стен храма.</p><p>Божественная магия позволяет исцелять, защищать и обрушивать возмездие. Жрец остаётся посредником, а не безмолвным сосудом: ему приходится толковать знамения, отвечать на сомнения и выбирать, как воплотить учение в несовершенном мире.</p><p>Его путь может начаться с откровения, долга перед общиной или попытки понять долгое молчание небес. Путешествуя, он не только несёт веру другим, но и узнаёт, какой она становится, когда привычные ответы перестают работать.</p>'),
      (ARRAY['artificer', 'изобретатель'],
       'Изобретатель соединяет ремесло и магию, превращая смелые идеи в работающие чудеса.',
       '<p>Изобретатель смотрит на волшебство как на материал: его можно измерить, направить и закрепить в предмете. Мастерская следует за ним в ящиках инструментов, карманах с реагентами и тетрадях, где удачные схемы соседствуют с впечатляющими неудачами.</p><p>Его сила проявляется в подготовленных устройствах, эликсирах и зачарованном снаряжении. В отличие от чистой теории, каждое изобретение должно выдержать дорогу, дождь и внезапное нападение — иначе оно остаётся лишь красивым чертежом.</p><p>В приключения мастера ведут редкие материалы, забытые технологии и задачи, которые никто ещё не решил. Лучшие из них знают, что ответственность за созданное не заканчивается в тот момент, когда механизм впервые оживает.</p>'),
      (ARRAY['warlock', 'колдун'],
       'Колдун получает необычайную силу через связь с таинственным потусторонним покровителем.',
       '<p>В основе пути колдуна лежит договор, обещание или контакт с сущностью, чьи намерения трудно измерить человеческой меркой. Одни сознательно искали такую силу, другие обнаружили связь случайно, третьи до сих пор спорят о том, был ли заключён настоящий договор.</p><p>Дар покровителя меняет привычную магию: тайные знаки обретают смысл, чужой шёпот приходит во сне, а простое заклинание несёт отпечаток далёкой воли. Колдун учится пользоваться этим даром, не позволяя ему полностью определить собственную судьбу.</p><p>Его приключение часто становится поиском границ соглашения. Он может выполнять поручение, искать способ освободиться, стремиться понять благодетеля или доказывать, что даже заёмная сила принадлежит тому, кто решает, как её применить.</p>'),
      (ARRAY['magus', 'магус'],
       'Магус соединяет искусство клинка с тайной магией в едином боевом стиле.',
       '<p>Магус не разделяет занятия в библиотеке и тренировку с оружием. Для него заклинание продолжается в движении клинка, а точный выпад может стать последним жестом сложной формулы.</p><p>Такое мастерство требует равновесия: сила без контроля разрушает технику, а слишком осторожная теория не выдерживает настоящего боя. Магус учится чувствовать дистанцию, темп и поток магии одновременно.</p><p>В путь его ведут редкие школы, утраченные приёмы и соперники, способные проверить искусство на пределе. Каждый бой становится опытом, который позже превратится в новую связку стали и чар.</p>'),
      (ARRAY['monk', 'монах'],
       'Монах развивает тело и дух, направляя внутреннюю энергию в совершенное движение.',
       '<p>Монах ищет мастерство через дисциплину. Его обучение может проходить в уединённой обители, городской школе или под руководством странствующего наставника, но всегда требует честного внимания к дыханию, мысли и движению.</p><p>Внутренняя энергия делает тело быстрым и точным инструментом. Монах уклоняется там, где другой принял бы удар, замечает момент между намерением и действием и отвечает ровно с той силой, которая необходима.</p><p>Путешествие проверяет спокойствие лучше любой тренировки. Одни монахи несут учение миру, другие ищут исчезнувшего учителя или пытаются примирить строгие идеалы с жизнью, где правильный ответ редко бывает очевиден.</p>'),
      (ARRAY['paladin', 'паладин'],
       'Паладин черпает силу в клятве, которой подчиняет оружие, волю и собственную жизнь.',
       '<p>Паладина создаёт не доспех и не титул, а обещание, принятое всерьёз. Его клятва может защищать слабых, хранить древний свет или преследовать великое зло, но всегда требует поступков, соответствующих произнесённым словам.</p><p>Убеждённость паладина становится ощутимой силой. Она поддерживает союзников, противостоит тьме и придаёт вес каждому удару, однако не освобождает от сомнений. Напротив, трудный выбор показывает, насколько глубоко укоренилась клятва.</p><p>Он отправляется в путь ради служения, искупления или дела, которое никто другой не готов принять. Настоящее испытание паладина начинается там, где буквальное правило расходится с духом обещания.</p>'),
      (ARRAY['rogue', 'плут'],
       'Плут побеждает наблюдательностью, точным расчётом и умением оказаться там, где его не ждут.',
       '<p>Плут знает цену информации и удачно выбранному моменту. Он замечает незапертую дверь, лишний взгляд охранника и слабое звено в чужом плане, превращая небольшое преимущество в решающий исход.</p><p>Не каждый плут преступник: среди них есть разведчики, сыщики, дипломаты и охотники за сокровищами. Их объединяет гибкость, уверенная работа руками и нежелание вести честный бой, если умный ход способен закончить дело быстрее.</p><p>В приключение плута ведут деньги, тайна, свобода или долг перед людьми, которым закон не помог. Со временем ему приходится решить, останется ли хитрость способом выжить или станет инструментом для чего-то большего.</p>'),
      (ARRAY['ranger', 'следопыт'],
       'Следопыт охраняет границу освоенного мира и знает повадки тех, кто скрывается за ней.',
       '<p>Следопыт проводит дни там, где заканчиваются дороги. Он читает следы, запоминает безопасные тропы и понимает, что тишина леса иногда сообщает об опасности больше, чем самый громкий сигнал тревоги.</p><p>Его мастерство соединяет оружие, выносливость и знание местности. Хороший следопыт не просто выслеживает добычу: он предугадывает её решения, выбирает место встречи и старается закончить опасность до того, как она доберётся до беззащитных.</p><p>В путь его ведут исчезновения, нарушенная граница или враг, которого никто другой не умеет найти. Долгое одиночество делает доверие редким, зато однажды признанных спутников следопыт ведёт через дикую землю как собственную стаю.</p>'),
      (ARRAY['sorcerer', 'чародей'],
       'Чародей владеет магией как врождённой частью себя, а не результатом учёбы или договора.',
       '<p>Магия чародея приходит из крови, случайного события или необъяснимого наследия. Она может пробудиться в детстве, во время опасности или после многих лет молчания, навсегда меняя отношения человека с самим собой.</p><p>Там, где волшебник следует записанной формуле, чародей чувствует заклинание изнутри и меняет его волей. Такая близость дарит свободу, но требует контроля: сильные эмоции способны сделать чудо ярче и одновременно опаснее.</p><p>Он путешествует, чтобы понять источник дара, найти похожих на себя или доказать, что происхождение не определяет назначение силы. Каждый новый предел магии становится одновременно открытием и вопросом о собственной природе.</p>'),
      (ARRAY['shaman', 'шаман'],
       'Шаман слышит духов мира и поддерживает связь между живыми, предками и природными силами.',
       '<p>Шаман замечает присутствие там, где другие видят лишь старое дерево, холодный ветер или пустой дом. Духи говорят образами, снами и знаками, а ответы редко бывают настолько прямыми, как хотелось бы просителю.</p><p>Его задача заключается не только в призыве силы, но и в поддержании отношений. Одних духов нужно успокоить, с другими договориться, третьим напомнить о забытом обещании. Ошибка в таком разговоре может отозваться далеко за пределами одного поселения.</p><p>В путешествие шамана ведёт нарушенный покой, зов предка или исчезновение привычных голосов. Между мирами он остаётся переводчиком и судьёй, который обязан помнить: не всё невидимое враждебно и не всякая помощь даётся без цены.</p>')
)
UPDATE dndshare.item class_item
SET data = jsonb_set(
    jsonb_set(class_item.data, '{short_description}', to_jsonb(lore.short_description), true),
    '{description}', to_jsonb(lore.description), true
)
FROM class_lore lore
WHERE class_item.user_id IS NULL
  AND class_item.parent_id IS NULL
  AND class_item.type_id = 9
  AND jsonb_typeof(class_item.data) = 'object'
  AND (
    regexp_replace(replace(lower(COALESCE(class_item.name_en, '')), 'ё', 'е'), '[^a-zа-я0-9]+', '', 'g') = ANY(lore.aliases)
    OR regexp_replace(replace(lower(class_item.name), 'ё', 'е'), '[^a-zа-я0-9]+', '', 'g') = ANY(lore.aliases)
  );
